PROGRAM ST240_SKRUVSTATION
VAR
    steg    : INT := 0;
    drag    : INT := 0;
    xPos    : INT := 0;
    xNokPos : INT := 0;
    xDrag   : BOOL := FALSE;
    xLas    : BOOL := FALSE;
    xStopp  : BOOL := FALSE;
    tmrLas  : TON;
    tmrVakt : TON;
END_VAR

(* Korsordningen 1, 3, 2, 4: drag nummer k borjar pa position 1, 3, 2 och 4.
   Den naturliga rakneordningen 1, 2, 3, 4 ar precis den miss uppgiften
   handlar om. *)
CASE drag OF
    1: xPos := 1;
    2: xPos := 3;
    3: xPos := 2;
    4: xPos := 4;
END_CASE;

(* Lasfonstret 0,10 s borjar nar spindeln stannat, alltsa pa ST240_SCR_DONE,
   sa att momentgivarens svarstid hinner ut med marginal. Vaktloppet 6,0 s
   borjar nar dragningen startat. *)
tmrLas(IN := xLas, PT := T#100ms);
tmrVakt(IN := xDrag AND NOT ST240_SCR_DONE, PT := T#6000ms);

IF NOT EMG_OK OR NOT AIR_OK THEN
    xDrag := FALSE;
    xLas := FALSE;
    steg := 0;
    drag := 0;
ELSE
    CASE steg OF
        0:
            IF ST240_PRT_PRS AND NOT xStopp THEN
                drag := 1;
                steg := 1;
            END_IF;
        1:
            xDrag := TRUE;
            steg := 2;
        2:
            IF ST240_SCR_DONE THEN
                xDrag := FALSE;
                xLas := TRUE;
                steg := 3;
            ELSIF tmrVakt.Q THEN
                (* DONE uteblir: spindeln stoppas och ingen ny position
                   borjar. *)
                xDrag := FALSE;
                xStopp := TRUE;
                steg := 9;
            END_IF;
        3:
            IF tmrLas.Q THEN
                xLas := FALSE;
                IF ST240_TRQ_VAL >= 20.0 AND ST240_TRQ_VAL <= 24.0 THEN
                    IF drag >= 4 THEN
                        steg := 5;
                    ELSE
                        drag := drag + 1;
                        steg := 1;
                    END_IF;
                ELSE
                    (* Utanfor fonstret 20,0 till 24,0 Nm: positionen
                       markeras och stationen stoppas. Ingen automatisk
                       omdragning. *)
                    xNokPos := xPos;
                    xStopp := TRUE;
                    steg := 9;
                END_IF;
            END_IF;
        5:
            (* Alla fyra positioner godkanda. *)
            IF NOT ST240_PRT_PRS THEN
                drag := 0;
                steg := 0;
            END_IF;
        9:
            (* Last til manuell atgard. *)
            xDrag := FALSE;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* En skrivning per utgang, forreglingarna i samma uttryck (F7): ingen
   dragning utan detalj, med brutet nodstopp eller utan tryckluft, och aldrig
   nar stationen ar stoppad pa en underkand skruv. *)
ST240_SCR_POS := xPos;
ST240_SCR_START := xDrag AND ST240_PRT_PRS AND EMG_OK AND AIR_OK
                   AND NOT xStopp;
ST240_NOK_POS := xNokPos;
ST240_STA_STOP := xStopp;
END_PROGRAM

